BEGIN;

CREATE TABLE "committee_task" (
    "task_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "committee_id" INTEGER NOT NULL,
    "title" VARCHAR(150) NOT NULL,
    "description" TEXT NOT NULL DEFAULT '',
    "assigned_member_id" INTEGER NOT NULL,
    "created_by_member_id" INTEGER NOT NULL,
    "due_at" TIMESTAMPTZ(3) NOT NULL,
    "priority" VARCHAR(10) NOT NULL DEFAULT 'MEDIUM',
    "status" VARCHAR(20) NOT NULL DEFAULT 'TODO',
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "committee_task_priority_check" CHECK ("priority" IN ('HIGH', 'MEDIUM', 'LOW')),
    CONSTRAINT "committee_task_status_check" CHECK ("status" IN ('TODO', 'IN_PROGRESS', 'COMPLETED')),
    CONSTRAINT "committee_task_committee_id_fkey" FOREIGN KEY ("committee_id") REFERENCES "committee"("committee_id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "committee_task_assignee_committee_fkey" FOREIGN KEY ("assigned_member_id", "committee_id") REFERENCES "member_committee"("member_id", "committee_id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "committee_task_creator_committee_fkey" FOREIGN KEY ("created_by_member_id", "committee_id") REFERENCES "member_committee"("member_id", "committee_id") ON DELETE RESTRICT ON UPDATE NO ACTION
);
CREATE INDEX "committee_task_committee_status_due_idx" ON "committee_task"("committee_id", "status", "due_at");
CREATE INDEX "committee_task_assignee_committee_status_idx" ON "committee_task"("assigned_member_id", "committee_id", "status");

CREATE TABLE "committee_point_entry" (
    "point_entry_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "committee_id" INTEGER NOT NULL,
    "member_id" INTEGER NOT NULL,
    "awarded_by_member_id" INTEGER NOT NULL,
    "points_delta" INTEGER NOT NULL,
    "reason" VARCHAR(500) NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "committee_point_entry_delta_check" CHECK ("points_delta" <> 0),
    CONSTRAINT "committee_point_entry_recipient_committee_fkey" FOREIGN KEY ("member_id", "committee_id") REFERENCES "member_committee"("member_id", "committee_id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "committee_point_entry_awarder_committee_fkey" FOREIGN KEY ("awarded_by_member_id", "committee_id") REFERENCES "member_committee"("member_id", "committee_id") ON DELETE RESTRICT ON UPDATE NO ACTION
);
CREATE INDEX "committee_point_entry_committee_created_idx" ON "committee_point_entry"("committee_id", "created_at", "point_entry_id");
CREATE INDEX "committee_point_entry_member_committee_created_idx" ON "committee_point_entry"("member_id", "committee_id", "created_at");

INSERT INTO "permission"("code", "description", "scope", "is_sensitive") VALUES
    ('dashboard.view', 'View committee dashboard data', 'committee', false),
    ('tasks.manage', 'Create and manage committee tasks', 'committee', false),
    ('points.manage', 'Award and deduct committee points', 'committee', false);

INSERT INTO "committee_permission"("committee_id", "committee_role", "code", "applies_to", "include_sub_committees") VALUES
    (NULL, 'Leader', 'dashboard.view', 'own', false),
    (NULL, 'Co-Leader', 'dashboard.view', 'own', false),
    (NULL, 'Member', 'dashboard.view', 'own', false),
    (NULL, 'Leader', 'tasks.manage', 'own', false),
    (NULL, 'Co-Leader', 'tasks.manage', 'own', false),
    (NULL, 'Leader', 'points.manage', 'own', false),
    (NULL, 'Co-Leader', 'points.manage', 'own', false);

COMMIT;
